package earth.terrarium.pastel.data.lang.guidebook.main;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class IntroEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.intro.description", "About the mod and how to get started");
		provider.add("book.pastel.guidebook.intro.name", "Intro");
		provider.add("book.pastel.guidebook.intro.page0.text", "Pastel is a progression and exploration-driven magic mod where you combine colors.");
		provider.add("book.pastel.guidebook.intro.page0.title", "Welcome to Pastel!");
		provider.add("book.pastel.guidebook.intro.page1.text", "You will be tinkering with color mixing in the subtractive color system (CMYK). You may be familiar with subtractive color mixing from watercolor painting or printing.\\\n\\\nThe main colors of the spectrum are represented with gemstones, you can find in geodes scattered around the world, with the vanilla Amethyst representing Magenta.");
		provider.add("book.pastel.guidebook.intro.page2.text", "Pastel features a unique progression system where you unlock new things as you progress.\\\nAs you progress, you will notice changes in the world. Differences that only *you* personally can perceive.\\\n\\\nEverything you learn will bring you closer to your ultimate goal: to find out what lies beneath the impenetrable bedrock floor.");
		provider.add("book.pastel.guidebook.intro.page2.title", "Progression System");
		provider.add("book.pastel.guidebook.intro.page3.link_text", "Pastel's Discord");
		provider.add("book.pastel.guidebook.intro.page3.text", "\\\nPastel is still in development. If you find any bugs report them to our github, and if you have a chance consider visiting the Terrarium discord!\\\n\\\nGo eat crayons ~ ~ ~ Azzyypaaras");
		provider.add("book.pastel.guidebook.intro.stuck.title", "No idea on how to progress?");
		provider.add("book.pastel.guidebook.intro.stuck.text", "Take a look at this book or your Pastel advancements. In both you will find nudges on what to do next.\\\n\\\nThere will be multiple advancement trees, one for each chapter of your journey.");
		provider.add("book.pastel.guidebook.intro.hints.title", "Optional Hint System");
		provider.add("book.pastel.guidebook.intro.hints.text", "Your Colorful World book comes with a hint system. If you ever are stuck feel free to consult these entries for a small hint - or the solution entirely.\\\n\\\nThey are purely optional - you will not lose out on anything if you use them. But of course you can pride yourself you finished the mod all by yourself!");
	}
}
